wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use aap::caps::notifier;

struct Node;

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        let mut message = format!("Digest {}\n{}\n", composed.date, composed.overview);
        for e in composed.entries.iter().filter(|e| e.kept) {
            message.push_str(&format!("- {} ({}): {}\n", e.title, e.link, e.summary));
        }

        let accepted = notifier::notify(&message);
        // The contract requires `published` to be present (true); never claim
        // publication that the notifier did not accept.
        if !accepted {
            panic!("notifier refused the digest");
        }

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published: true,
        }
    }
}

export!(Node);
